# Creates (or recreates) the chinook database on a PostgreSQL server for the Chinook samples:
#   1. downloads Chinook 1.4.5 (MIT, https://github.com/lerocha/chinook-database) once, into target/chinook/,
#      and checks its SHA-256;
#   2. runs it, which drops and recreates the chinook database;
#   3. runs chinook-mcp-postgresql.sql: lock versions, generated keys, and the mcp_reader and mcp_store accounts.
#
# Run from the repository root as a PostgreSQL superuser. psql's usual variables pick the server:
#   PGHOST=localhost PGUSER=postgres sh samples/chinook/db/setup-postgresql.sh
set -eu

VERSION=v1.4.5
URL="https://raw.githubusercontent.com/lerocha/chinook-database/$VERSION/ChinookDatabase/DataSources/Chinook_PostgreSql.sql"
SHA256=e3fde5c1a5b51a2a91429a702c9ca6e69ba56e6c7f5e112724d70c3d03db695e
DIR=target/chinook
SCRIPT="$DIR/Chinook_PostgreSql.sql"
HERE=$(dirname "$0")

mkdir -p "$DIR"
if [ ! -f "$SCRIPT" ]; then
  echo "Downloading Chinook $VERSION"
  curl -fsSL -o "$SCRIPT.part" "$URL"
  mv "$SCRIPT.part" "$SCRIPT"
fi
if command -v sha256sum >/dev/null 2>&1; then
  ACTUAL=$(sha256sum "$SCRIPT" | cut -d' ' -f1)
else
  ACTUAL=$(shasum -a 256 "$SCRIPT" | cut -d' ' -f1)
fi
if [ "$ACTUAL" != "$SHA256" ]; then
  echo "$SCRIPT has SHA-256 $ACTUAL, expected $SHA256. Delete it and run again." >&2
  exit 1
fi

psql -v ON_ERROR_STOP=1 -q -d postgres -f "$SCRIPT"
psql -v ON_ERROR_STOP=1 -q -d chinook -f "$HERE/chinook-mcp-postgresql.sql"
echo "chinook is ready: mcp_reader (password reader) reads it, mcp_store (password store) writes for music-store"
